sysevent_script_action.script:
// Call a function to create a Scheduled Import for the attachment
// given in @current. This is a newly arrived attachment on
// data source Vendor Data Queue.
queueNextImport(current);

/**
 * @current  A file attachment newly arrived on data source Vendor Data Queue.
 * 
 */
function queueNextImport(current) {
    //var vendor_data_sys_id = "";
    //var vendor_data_archive_sys_id = "";

    // A new data file has arrived and is parked on "Vendor Data Queue".

    // Queue the file up for import via data source "Vendor Data", unless...

	gs.info("queueNextImport 1");

    // ...Exit if there is a Scheduled Data Import for this data source
    // with a future run date.
    var util = new x_42999_import_v_0.VendorDataUtils();
    var gdtNow = new GlideDateTime();
    var scope = gs.getCurrentApplicationId();
	gs.info("scope is " + scope);
    var activeOnly = true;
    var answer = util.hasScheduledImportAfter(scope, "Vendor Data", activeOnly, gdtNow);
    if (answer == true) {
        gs.warn("There is an existing scheduled import for this data. Exiting.");
        return;
    }

	gs.info("queueNextImport 2");

    // Copy all attachments from "Vendor Data" to "Vendor Data Archive",
    // and remove originals

    // A gr of attachments to copy
gs.info("Vendor Data sys_id is " + util.getDataSourceSysId(scope, "Vendor Data"));

    var gr_attachments = new GlideRecord("sys_attachment");
    gr_attachments.addQuery("table_name", "sys_data_source");
    gr_attachments.addQuery("table_sys_id", util.getDataSourceSysId(scope, "Vendor Data"));
    gr_attachments.query();

	while(gr_attachments.next()) gs.info(gr_attachments.getValue("file_name"));

	gs.info("queueNextImport 3");

    // gr to copy attachments to
    // var gr_target = new GlideRecord("sys_data_source");
    // gr_target.addQuery("table_sys_id", util.getDataSourceSysId(scope, "Vendor Data Archive"));
	// gr_target.setLimit(1);
    // gr_target.query();
    // var new_sys_ids = util.copyAttachments(
    //     gr_attachments, 
	// 	gr_target
    // );

	//gs.info("queueNextImport 4");

    //util.deleteAttachments("sys_data_source",  util.getDataSourceSysId(scope, "Vendor Data"));

	//gs.info("queueNextImport 5");

    // copy @current to Vendor Data and delete the original
	// gr_target = new GlideRecord("sys_data_source");
    // gr_target.addQuery("table_sys_id", util.getDataSourceSysId(scope, "Vendor Data"));
	// gr_target.setLimit(1);
    // gr_target.query();
    // util.copyAttachment(current, gr_target);

	//gs.info("queueNextImport 5");

	//util.deleteAttachments("sys_data_source",  util.getDataSourceSysId(scope, "Vendor Data Queue"));

	//gs.info("queueNextImport 6");

    // Create a Scheduled Data Import for Vendor Data, set it to run soon.

    // The import's name will reflect when the file was received.
    // The run time may lag this, esp if multiple files are received
    // about the same time.
    //var name = "Vendor Data " + current.getValue("sys_created_on");

	//gs.info("queueNextImport 7");

    // run time
    // var gdt = new GlideDateTime();
    // gdt.addSeconds(5);
    // var runStart = gdt.getDisplayValue();
    // var runType = "once";
    // util.createScheduledImport(
    //     scope,
    //     name,
    //     util.getDataSourceSysId(scope, "Vendor Data"),
    //     runStart,
    //     runType);

	//gs.info("queueNextImport 8");

}
